/*
 * Toolbar styles for Kitsaas on top of @ui-sdk/solid/toolbar.
 *
 * Attribute-driven rules (`data-orientation`, `data-disabled`, `data-open`)
 * using semantic `--v2-*` tokens that flip automatically with
 * `[data-color-scheme="dark"]`.
 */

@layer components {
  [data-slot="toolbar"] {
    display: inline-flex;
    flex-direction: row;
    flex-wrap: wrap;
    align-items: center;
    gap: 2px;
    max-width: 100%;
    padding: 4px;
    border-radius: 8px;
    border: 1px solid var(--v2-border-border-base);
    background-color: var(--v2-background-bg-layer-01);
    color: var(--v2-text-text-base);
  }

  [data-slot="toolbar"][data-orientation="vertical"] {
    flex-direction: column;
    align-items: stretch;
  }

  [data-slot="toolbar-group"] {
    display: inline-flex;
    flex-direction: row;
    align-items: center;
    gap: 2px;
  }

  [data-slot="toolbar-group"][data-orientation="vertical"] {
    flex-direction: column;
    align-items: stretch;
  }

  /* Seamless integration for ToggleGroup & Toggle placed inside Toolbar */
  [data-slot="toolbar"] [data-slot="toggle-group"] {
    padding: 0;
    border-radius: 0;
    background-color: transparent;
    box-shadow: none;
  }

  [data-slot="toolbar"] [data-slot="toggle"] {
    border-radius: 4px;
  }

  [data-slot="toolbar-button"],
  [data-slot="toolbar-link"] {
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    height: 28px;
    min-width: 28px;
    padding: 0 8px;
    border: 0;
    border-radius: 4px;
    background-color: transparent;
    color: var(--v2-text-text-base);
    font-family: var(--font-family-sans);
    font-style: normal;
    font-weight: 530;
    font-size: 13px;
    line-height: 20px;
    letter-spacing: -0.04px;
    font-variant-numeric: tabular-nums;
    text-decoration: none;
    white-space: nowrap;
    user-select: none;
    cursor: pointer;
    outline: none;
    transition:
      background-color 100ms ease,
      color 100ms ease;
  }

  [data-slot="toolbar-button"]:has(> svg:only-child) {
    width: 28px;
    padding: 0;
    color: var(--v2-icon-icon-base);
  }

  [data-slot="toolbar-button"] > svg,
  [data-slot="toolbar-link"] > svg {
    width: 16px;
    height: 16px;
    flex-shrink: 0;
    color: currentColor;
  }

  [data-slot="toolbar-link"] {
    font-weight: 440;
    color: var(--v2-text-text-muted);
  }

  @media (hover: hover) {
    [data-slot="toolbar-button"]:hover:not(:disabled, [data-disabled]),
    [data-slot="toolbar-link"]:hover:not([data-disabled]) {
      background-color: var(--v2-overlay-simple-overlay-hover);
      color: var(--v2-text-text-base);
    }
  }

  [data-slot="toolbar-button"]:is(:active, [data-open]):not(:disabled, [data-disabled]),
  [data-slot="toolbar-link"]:active:not([data-disabled]) {
    background-color: var(--v2-overlay-simple-overlay-pressed);
    color: var(--v2-text-text-base);
  }

  [data-slot="toolbar-button"]:focus-visible,
  [data-slot="toolbar-link"]:focus-visible {
    outline: 2px solid var(--v2-border-border-focus);
    outline-offset: 2px;
    z-index: 1;
  }

  [data-slot="toolbar-button"]:is(:disabled, [data-disabled]),
  [data-slot="toolbar-link"][data-disabled] {
    opacity: 0.5;
    cursor: not-allowed;
  }

  [data-slot="toolbar-input"] {
    box-sizing: border-box;
    width: 152px;
    min-width: 0;
    height: 28px;
    padding: 0 8px;
    margin: 0;
    border: 0;
    border-radius: 6px;
    outline: 1px solid transparent;
    outline-offset: -1px;
    background: var(--v2-background-bg-base);
    box-shadow: var(--v2-elevation-input);
    color: var(--v2-text-text-base);
    font-family: var(--font-family-sans);
    font-style: normal;
    font-weight: 440;
    font-size: 13px;
    line-height: var(--line-height-compact);
    letter-spacing: -0.04px;
    transition:
      outline-color 85ms ease-out,
      box-shadow 85ms ease-out;
  }

  [data-slot="toolbar-input"]::placeholder {
    color: var(--v2-text-text-faint);
    user-select: none;
  }

  [data-slot="toolbar-input"]:focus {
    outline-color: var(--v2-border-border-focus);
    box-shadow: none;
  }

  [data-slot="toolbar-input"]:is(:disabled, [data-disabled]) {
    opacity: 0.5;
    cursor: not-allowed;
  }

  [data-slot="toolbar-separator"] {
    flex-shrink: 0;
    align-self: center;
    width: 1px;
    height: 18px;
    margin: 0 4px;
    background-color: var(--v2-border-border-base);
  }

  [data-slot="toolbar-separator"][data-orientation="horizontal"] {
    align-self: stretch;
    width: auto;
    height: 1px;
    margin: 4px 2px;
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="toolbar-button"],
    [data-slot="toolbar-link"],
    [data-slot="toolbar-input"] {
      transition: none;
    }
  }
}
